import 'package:flutter/material.dart';
import '../../services/api_client.dart';
import '../../services/session.dart';

class ExecutiveRiskDecisionScreen extends StatefulWidget { const ExecutiveRiskDecisionScreen({super.key}); @override State<ExecutiveRiskDecisionScreen> createState()=>_ExecutiveRiskDecisionScreenState(); }
class _ExecutiveRiskDecisionScreenState extends State<ExecutiveRiskDecisionScreen>{ final api=ApiClient(); List<dynamic> items=[]; String? error; Future<void> load() async { api.token=await Session.getToken(); try{ final d=await api.get('/admin/executive-risk-decisions'); items=(d['items'] as List?)??[]; error=null;}catch(e){error=e.toString();} if(mounted)setState((){}); }
 Future<void> decide(Map<String,dynamic> item) async { final c=TextEditingController(); final ok=await showDialog<bool>(context:context,builder:(_)=>AlertDialog(title:Text('Decisão #${item['id']}'),content:TextField(controller:c,maxLines:4,decoration:const InputDecoration(labelText:'Justificativa obrigatória')),actions:[TextButton(onPressed:()=>Navigator.pop(context,false),child:const Text('Cancelar')),ElevatedButton(onPressed:()=>Navigator.pop(context,true),child:const Text('Registrar'))])); if(ok!=true||c.text.trim().isEmpty)return; try{api.token=await Session.getToken(); await api.post('/admin/executive-risk-decisions/${item['id']}/decide',{'decision':'DEFER','rationale':c.text.trim()}); await load();}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(e.toString())));} }
 @override void initState(){super.initState();load();} @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Centro de Decisão')),body:RefreshIndicator(onRefresh:load,child:ListView(padding:const EdgeInsets.all(12),children:[if(error!=null)Text(error!),...items.map((x)=>Card(child:ListTile(title:Text('Decisão #${x['id']} — ${x['priority']}'),subtitle:Text('${x['decision_type']} • ${x['status']}'),trailing:x['status']=='PENDING'?IconButton(icon:const Icon(Icons.gavel),onPressed:()=>decide(x)):const Icon(Icons.check_circle_outline))))]))); }
